#!/usr/bin/env npx tsx
// Builds the evaluation manifests for the repository's synthetic fixtures from
// their tracked sources, so labels are derived mechanically rather than typed:
//   test-assets/sample-plan-E101-E102.pdf + sample-plan-truth.json
//     (generated by scripts/make_sample_plan.py)
//   e2e/fixtures/sample-plan.pdf (generated by scripts/make-sample-plan.mjs)
//
// Usage:
//   npx tsx scripts/eval/make-synthetic-manifests.ts          write manifests
//   npx tsx scripts/eval/make-synthetic-manifests.ts --check  exit 1 if stale

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { sha256, type PageBox, type LabeledRegion } from "./manifest";

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
export const MANIFEST_DIR = "evaluation/manifests";

const round = (v: number) => Math.round(v * 10000) / 10000;
const box = (x: number, y: number, w: number, h: number): PageBox => ({ x: round(x), y: round(y), w: round(w), h: round(h) });
const fileSha = (rel: string) => sha256(readFileSync(path.join(REPO_ROOT, rel)));

const SYNTHETIC_GATES = {
  minPrecision: 1, minRecall: 1, maxFalsePositives: 0, maxFalseNegatives: 0, maxNegativeHits: 0, maxApiCalls: 0, allowedStatus: ["completed"],
};
const APP_DEFAULTS = {
  // SymbolSearch defaults: Balanced 72% threshold, no ±10% size tolerance, local only.
  detector: { minScore: 0.72, scaleTolerance: false },
  render: { scale: "symbol-search" },
  scoring: { rule: "center-distance", radius: "truth-half-diagonal", radiusScale: 1 },
  labelProvenance: "synthetic-generator",
};

// Legend swatches drawn by draw_legend() in scripts/make_sample_plan.py on both
// sheets (reportlab origin bottom-left, page height 1728). Converted to top-left
// boxes and padded 1 pt for stroke width. A detection here is a false positive.
function sampleLegendNegatives(pageHeight: number): LabeledRegion[] {
  const x = 250, rowY = (i: number) => 1524 + 150 - 48 - 28 * i; // legend y + h - 48, then 28 pt per row
  const topLeft = (left: number, bottom: number, w: number, h: number) => box(left - 1, pageHeight - (bottom + h) - 1, w + 2, h + 2);
  return [
    { label: "legend swatch: duplex", box: topLeft(x + 30 - 6, rowY(0) - 9, 12, 18) },
    { label: "legend swatch: troffer", box: topLeft(x + 12, rowY(1) - 8, 36, 16) },
    // Helvetica-Bold 13 pt "S" centred at x + 30 on baseline rowY(2) - 5.
    { label: "legend swatch: switch", box: topLeft(x + 30 - 5, rowY(2) - 5 - 0.5, 10, 10.5) },
    { label: "legend swatch: exit", box: topLeft(x + 20, rowY(3) - 5, 20, 10) },
  ];
}

interface TruthSymbol { kind: string; x: number; y: number; w: number; h: number }
interface TruthSheet { sheet_no: string; page_number: number; width: number; height: number; symbols: TruthSymbol[] }

function samplePlanManifest() {
  const pdf = "test-assets/sample-plan-E101-E102.pdf", truthPath = "test-assets/sample-plan-truth.json";
  const truth = JSON.parse(readFileSync(path.join(REPO_ROOT, truthPath), "utf8")) as { sheets: TruthSheet[] };
  // Same four fixtures, order and example symbol as the historical
  // scripts/eval-local-detection.ts run (first symbol of the kind in truth order).
  const cases = [["E-102", "troffer"], ["E-101", "duplex"], ["E-102", "switch"], ["E-102", "exit"]].map(([sheetNo, kind]) => {
    const sheet = truth.sheets.find(s => s.sheet_no === sheetNo)!;
    const symbols = sheet.symbols.filter(s => s.kind === kind);
    const toBox = (s: TruthSymbol) => box(s.x - s.w / 2, s.y - s.h / 2, s.w, s.h);
    return {
      id: `${sheetNo}-${kind}`,
      input: "sample-plan",
      page: sheet.page_number,
      sheet: sheetNo,
      symbolClass: kind,
      example: { box: toBox(symbols[0]), note: `first ${kind} in ${truthPath} order (historical render_eval_tiles.py convention)` },
      expected: symbols.map(toBox),
      negatives: sampleLegendNegatives(sheet.height),
      ignore: [],
    };
  });
  return {
    $comment: "Generated by scripts/eval/make-synthetic-manifests.ts. Do not edit by hand; regenerate and review the diff.",
    format: "voltline-detection-eval",
    version: 1,
    id: "synthetic-sample-plan",
    description: "Synthetic ARCH D two-sheet plan (E-101 power, E-102 lighting) with exact generator labels. Excluded: the single LP-1 panel (one instance gives no count signal).",
    evidenceClass: "synthetic",
    coordinateConvention: "pdf-top-left-points",
    inputs: {
      "sample-plan": {
        kind: "pdf", fixtureId: "voltline-synthetic-sample-plan-e101-e102", redistributable: true, path: pdf, sha256: fileSha(pdf),
        generator: "scripts/make_sample_plan.py", labels: { path: truthPath, sha256: fileSha(truthPath) },
      },
    },
    defaults: { ...APP_DEFAULTS, split: { project: "synthetic-sample-plan", source: "scripts/make_sample_plan.py", set: "regression" }, gates: SYNTHETIC_GATES },
    cases,
  };
}

// Positions hard-coded in scripts/make-sample-plan.mjs (pdf-lib, bottom-left
// origin, 612 × 792 pages). Receptacle: radius-6 circle plus ±9 pt ticks at
// y ± 3, so an 18 × 12 box. Fixture: 24 × 12 rectangle with an X.
function e2ePlanManifest() {
  const pdf = "e2e/fixtures/sample-plan.pdf", generator = "scripts/make-sample-plan.mjs";
  const H = 792;
  const receptacle = ([x, y]: number[]) => box(x - 9, H - y - 6, 18, 12);
  const fixture = ([x, y]: number[]) => ({ label: "other class: 2x4 fixture", box: box(x - 12 - 1, H - y - 6 - 1, 26, 14) });
  const page1 = [[80, 150], [80, 400], [80, 650], [520, 150], [520, 400], [520, 650]];
  const fixtures = [[200, 250], [400, 250], [200, 550], [400, 550]];
  const page2 = [[150, 200], [300, 500], [450, 200]];
  // The phase-4 E2E test boxes (66, 628)–(94, 656) around the receptacle at (80, 150).
  const exampleAround = ([x, y]: number[]) => box(x - 14, H - y - 14, 28, 28);
  return {
    $comment: "Generated by scripts/eval/make-synthetic-manifests.ts. Do not edit by hand; regenerate and review the diff.",
    format: "voltline-detection-eval",
    version: 1,
    id: "synthetic-e2e-plan",
    description: "Small synthetic letter-size plan used by the phase-4 auto-count E2E test; receptacle counts per page, labels from the generator's hard-coded positions.",
    evidenceClass: "synthetic",
    coordinateConvention: "pdf-top-left-points",
    inputs: {
      "e2e-plan": {
        kind: "pdf", fixtureId: "voltline-synthetic-e2e-sample-plan", redistributable: true, path: pdf, sha256: fileSha(pdf),
        generator, labels: { path: generator, sha256: fileSha(generator) },
      },
    },
    defaults: { ...APP_DEFAULTS, split: { project: "synthetic-e2e-plan", source: generator, set: "regression" }, gates: SYNTHETIC_GATES },
    cases: [
      {
        id: "p1-receptacle", input: "e2e-plan", page: 1, sheet: "E-101 (E2E)", symbolClass: "receptacle",
        example: { box: exampleAround(page1[0]), note: "same 28 × 28 pt example box the phase-4 E2E test draws" },
        expected: page1.map(receptacle), negatives: fixtures.map(fixture), ignore: [],
      },
      {
        id: "p2-receptacle", input: "e2e-plan", page: 2, sheet: "E-102 (E2E)", symbolClass: "receptacle",
        example: { box: exampleAround(page2[0]), note: "28 × 28 pt box around the first page-2 receptacle" },
        expected: page2.map(receptacle), negatives: [], ignore: [],
      },
    ],
  };
}

export function buildSyntheticManifests(): Record<string, string> {
  const text = (value: unknown) => JSON.stringify(value, null, 2) + "\n";
  return {
    [`${MANIFEST_DIR}/synthetic-sample-plan.v1.json`]: text(samplePlanManifest()),
    [`${MANIFEST_DIR}/synthetic-e2e-plan.v1.json`]: text(e2ePlanManifest()),
  };
}

function main() {
  const check = process.argv.includes("--check");
  let stale = 0;
  for (const [rel, text] of Object.entries(buildSyntheticManifests())) {
    const file = path.join(REPO_ROOT, rel);
    let current = "";
    try { current = readFileSync(file, "utf8"); } catch { /* missing */ }
    if (current === text) { console.log(`up to date: ${rel}`); continue; }
    if (check) { console.error(`stale: ${rel}`); stale++; continue; }
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, text);
    console.log(`wrote ${rel}`);
  }
  if (stale) process.exitCode = 1;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) main();
